create table public.audit_logs(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,actor_user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,summary text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index audit_logs_school_created_idx on public.audit_logs(school_id,created_at desc);create index audit_logs_entity_idx on public.audit_logs(school_id,entity_type,entity_id);
create table public.notifications(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,student_id uuid references public.students(id) on delete cascade,type text not null,title text not null,body text not null,link text,read_at timestamptz,created_at timestamptz not null default now());
create index notifications_user_idx on public.notifications(user_id,read_at,created_at desc);create index notifications_student_idx on public.notifications(student_id,created_at desc);
alter table public.audit_logs enable row level security;alter table public.notifications enable row level security;
create policy "audit managers read" on public.audit_logs for select to authenticated using(public.has_school_role(school_id,array['school_owner','principal']::public.school_role[]));
create policy "staff create audit" on public.audit_logs for insert to authenticated with check(actor_user_id=(select auth.uid()) and public.has_school_role(school_id,array['school_owner','principal','teacher','accountant','reception']::public.school_role[]));
create policy "notification recipient read" on public.notifications for select to authenticated using(user_id=(select auth.uid()) or (student_id is not null and public.can_view_student(student_id)));
create policy "notification recipient update" on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "staff create notifications" on public.notifications for insert to authenticated with check(public.has_school_role(school_id,array['school_owner','principal','teacher','accountant','reception']::public.school_role[]));